def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    orbits = {planet: index for index, planet in enumerate(planets)}

    if planet1 not in planets or planet2 not in planets:
        return ()

    start = min(orbits[planet1], orbits[planet2])
    end = max(orbits[planet1], orbits[planet2])

    result = [planet for planet in planets if start < orbits[planet] < end]

    return tuple(sorted(result, key=lambda x: orbits[x]))

